-- Generated by scripts/import-restroom.mjs from a restroom-map cluster backup.
-- Do not edit once applied: the runner's hash check will refuse it.

create extension if not exists postgis with schema extensions;
set search_path = restroom, public, extensions;

CREATE TYPE restroom.access_field AS ENUM (
    'wheelchair',
    'changing_table',
    'gender_neutral',
    'adult_changing',
    'grab_bars',
    'turning_space',
    'accessible_locked',
    'sink_in_stall',
    'shelf',
    'hours'
);
CREATE TYPE restroom.access_kind AS ENUM (
    'open',
    'code_required',
    'ask_staff',
    'customers_only'
);
CREATE TYPE restroom.adult_changing_kind AS ENUM (
    'changing_places',
    'bench',
    'none'
);
CREATE TYPE restroom.bathroom_status AS ENUM (
    'active',
    'hidden',
    'removed'
);
CREATE TYPE restroom.changing_table_access AS ENUM (
    'any',
    'women_only',
    'men_only',
    'none'
);
CREATE TYPE restroom.credit_reason AS ENUM (
    'signup_bonus',
    'submission_verified',
    'code_verified',
    'passive_confirmation',
    'fraud_clawback',
    'spend_unlock',
    'manual_adjustment'
);
CREATE TYPE restroom.hours_kind AS ENUM (
    'always',
    'daylight',
    'venue'
);
CREATE TYPE restroom.report_kind AS ENUM (
    'works',
    'code_bad',
    'gone',
    'inaccessible',
    'dirty'
);
CREATE TYPE restroom.venue_type AS ENUM (
    'store',
    'restaurant',
    'cafe',
    'gas_station',
    'park',
    'transit',
    'public_facility',
    'library',
    'hotel',
    'other'
);
CREATE TYPE restroom.wheelchair_access AS ENUM (
    'full',
    'partial',
    'none'
);
CREATE TABLE restroom.access_claims (
    bathroom_id uuid NOT NULL,
    field restroom.access_field NOT NULL,
    value text NOT NULL,
    user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE restroom.bathroom_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bathroom_id uuid NOT NULL,
    code text NOT NULL,
    submitted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by uuid,
    CONSTRAINT bathroom_codes_code_check CHECK (((length(code) >= 1) AND (length(code) <= 40)))
);
CREATE TABLE restroom.bathrooms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    geog extensions.geography(Point,4326) NOT NULL,
    name text NOT NULL,
    venue_type restroom.venue_type NOT NULL,
    access_kind restroom.access_kind DEFAULT 'open'::restroom.access_kind NOT NULL,
    address text,
    floor_hint text,
    gender_neutral boolean,
    status restroom.bathroom_status DEFAULT 'active'::restroom.bathroom_status NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    hidden_reason text,
    hidden_at timestamp with time zone,
    import_source text,
    import_id text,
    import_licence text,
    wheelchair restroom.wheelchair_access,
    changing_table restroom.changing_table_access,
    operator text,
    adult_changing restroom.adult_changing_kind,
    grab_bars boolean,
    turning_space boolean,
    accessible_locked boolean,
    sink_in_stall boolean,
    shelf boolean,
    hours restroom.hours_kind,
    closed_in_winter boolean,
    CONSTRAINT bathrooms_name_check CHECK (((length(name) >= 1) AND (length(name) <= 120)))
);
CREATE TABLE restroom.reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bathroom_id uuid NOT NULL,
    code_id uuid,
    user_id uuid,
    anon_id text,
    kind restroom.report_kind NOT NULL,
    geo_verified boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE restroom.code_unlocks (
    user_id uuid NOT NULL,
    bathroom_id uuid NOT NULL,
    unlocked_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE restroom.comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bathroom_id uuid NOT NULL,
    user_id uuid NOT NULL,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    hidden_at timestamp with time zone,
    hidden_reason text,
    CONSTRAINT comments_body_check CHECK (((length(body) >= 1) AND (length(body) <= 1000)))
);
CREATE TABLE restroom.credit_ledger (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    delta integer NOT NULL,
    reason restroom.credit_reason NOT NULL,
    ref_type text,
    ref_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
