ALTER TABLE restroom.access_claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE restroom.bathroom_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE restroom.bathrooms ENABLE ROW LEVEL SECURITY;
