CREATE VIEW restroom.bathroom_confidence WITH (security_invoker='true') AS
 SELECT b.id AS bathroom_id,
    (count(*) FILTER (WHERE ((r.kind = 'works'::restroom.report_kind) AND (r.created_at > (now() - '90 days'::interval)))))::integer AS confirms_90d,
    (count(*) FILTER (WHERE ((r.kind = ANY (ARRAY['gone'::restroom.report_kind, 'code_bad'::restroom.report_kind])) AND (r.created_at > (now() - '90 days'::interval)))))::integer AS troubles_90d,
    max(r.created_at) FILTER (WHERE (r.kind = 'works'::restroom.report_kind)) AS last_confirmed_at,
    (COALESCE(sum((
        CASE
            WHEN (r.kind = 'works'::restroom.report_kind) THEN 1.0
            ELSE '-2.0'::numeric
        END * exp(((- EXTRACT(epoch FROM (now() - r.created_at))) / 2592000.0)))), (0)::numeric))::numeric(6,2) AS score,
    (count(DISTINCT COALESCE((r.user_id)::text, r.anon_id)) FILTER (WHERE ((r.kind = ANY (ARRAY['gone'::restroom.report_kind, 'code_bad'::restroom.report_kind])) AND (r.created_at > (now() - '90 days'::interval)))))::integer AS trouble_reporters_90d
   FROM (restroom.bathrooms b
     LEFT JOIN restroom.reports r ON ((r.bathroom_id = b.id)))
  GROUP BY b.id;
CREATE VIEW restroom.moderation_queue AS
 SELECT f.id,
    f.created_at,
    f.target_type,
    f.target_id,
    f.message AS reason,
    f.contact_email,
    b.name AS bathroom_name,
    b.status AS bathroom_status,
    c.confirms_90d,
    c.troubles_90d,
    c.score,
    (f.contact_email IS NOT NULL) AS awaiting_reply
   FROM ((public.flags f
     LEFT JOIN restroom.bathrooms b ON (((f.target_type = 'bathroom'::text) AND (b.id = f.target_id))))
     LEFT JOIN restroom.bathroom_confidence c ON ((c.bathroom_id = b.id)))
  WHERE (f.resolved_at IS NULL AND f.app = 'restroom-map')
UNION ALL
 SELECT d.id,
    d.created_at,
    (('feedback: '::text || (d.kind)::text) || COALESCE((' · '::text || d.build), ''::text)) AS target_type,
    NULL::uuid AS target_id,
    d.message AS reason,
    d.contact_email,
    NULL::text AS bathroom_name,
    NULL::restroom.bathroom_status AS bathroom_status,
    NULL::integer AS confirms_90d,
    NULL::integer AS troubles_90d,
    NULL::numeric(6,2) AS score,
    (d.contact_email IS NOT NULL) AS awaiting_reply
   FROM public.feedback d
  WHERE (d.resolved_at IS NULL AND d.app = 'restroom-map')
  ORDER BY 12 DESC, 2 DESC;
CREATE VIEW restroom.user_credits WITH (security_invoker='true') AS
 SELECT user_id,
    (sum(delta))::integer AS balance
   FROM restroom.credit_ledger
  GROUP BY user_id;
CREATE FUNCTION restroom.apply_auto_hide() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_score     numeric;
  v_reporters int;
  v_owner     uuid;
begin
  if NEW.kind not in ('gone', 'code_bad') then
    return NEW;
  end if;

  select score, trouble_reporters_90d into v_score, v_reporters
  from bathroom_confidence where bathroom_id = NEW.bathroom_id;

  if coalesce(v_score, 0) < -3 and coalesce(v_reporters, 0) >= 3 then
    update bathrooms
    set status = 'hidden',
        hidden_at = now(),
        hidden_reason = format('auto-hidden: score %s from %s reporters',
                               round(v_score, 2), v_reporters)
    where id = NEW.bathroom_id and status = 'active'
    returning created_by into v_owner;

    if v_owner is not null and exists (
      select 1 from credit_ledger
      where reason = 'submission_verified' and ref_id = NEW.bathroom_id
    ) then
      values (v_owner, -10, 'fraud_clawback', 'bathroom', NEW.bathroom_id)
      on conflict do nothing;
    end if;

    values ('bathroom', NEW.bathroom_id, 'auto-hidden: sustained trouble reports');
  end if;

  return NEW;
end $$;
CREATE FUNCTION restroom.award_on_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_owner      uuid;
  v_confirms   int;
  v_geo        int;
  v_code_owner uuid;
begin
  -- Anonymous reports inform freshness. They never move credits: a cleared
  -- cookie must not be worth anything.
  if NEW.kind <> 'works' or NEW.user_id is null then
    return NEW;
  end if;

  select created_by into v_owner from bathrooms where id = NEW.bathroom_id;
  if v_owner is null then
    return NEW;   -- imported row, nobody to pay
  end if;

  -- ESCROW RELEASE. Confirmations only count from accounts older than a day,
  -- so a batch of sockpuppets minted this morning cannot release anything.
  select count(distinct r.user_id),
         count(distinct r.user_id) filter (where r.geo_verified)
    into v_confirms, v_geo
  from reports r
  join profiles p on p.id = r.user_id
  where r.bathroom_id = NEW.bathroom_id
    and r.kind = 'works'
    and r.user_id is distinct from v_owner
    and p.created_at < now() - interval '24 hours';

  if v_confirms >= 3 and v_geo >= 2 then
    values (v_owner, 10, 'submission_verified', 'bathroom', NEW.bathroom_id)
    on conflict do nothing;              -- ledger_dedupe pays exactly once
  end if;

  -- The code that was actually tested.
  if NEW.code_id is not null then
    select submitted_by into v_code_owner
    from bathroom_codes where id = NEW.code_id;

    if v_code_owner is not null and v_code_owner is distinct from NEW.user_id then
      -- First independent confirmation of this specific code row.
      values (v_code_owner, 5, 'code_verified', 'code', NEW.code_id)
      on conflict do nothing;

      -- And a trickle per confirmation, capped so a popular code is not a
      -- salary.
      if daily_passive(v_code_owner) < 10 then
        values (v_code_owner, 1, 'passive_confirmation', 'report', NEW.id)
        on conflict do nothing;
      end if;
    end if;
  end if;

  return NEW;
end $$;
CREATE FUNCTION restroom.bathrooms_in_view(min_lng double precision, min_lat double precision, max_lng double precision, max_lat double precision, types restroom.venue_type[] DEFAULT NULL::restroom.venue_type[], access restroom.access_kind[] DEFAULT NULL::restroom.access_kind[], max_results integer DEFAULT 300, needs text[] DEFAULT NULL::text[]) RETURNS TABLE(id uuid, lat double precision, lng double precision, name text, venue_type restroom.venue_type, access_kind restroom.access_kind, has_code boolean, confirms integer, troubles integer, last_confirmed timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
  select
    b.id,
    st_y(b.geog::geometry), st_x(b.geog::geometry),
    b.name, b.venue_type, b.access_kind,
    exists(select 1 from bathroom_codes c
           where c.bathroom_id = b.id and c.superseded_at is null),
    coalesce(f.confirms_90d, 0),
    coalesce(f.troubles_90d, 0),
    f.last_confirmed_at
  from bathrooms b
  left join bathroom_confidence f on f.bathroom_id = b.id
  where b.status = 'active'
    and b.geog && st_makeenvelope(min_lng, min_lat, max_lng, max_lat, 4326)::geography
    and (types  is null or b.venue_type  = any(types))
    and (access is null or b.access_kind = any(access))
    and (needs is null or (
      (not ('changing'       = any(needs)) or b.changing_table in ('any','women_only','men_only'))
      and (not ('step_free'      = any(needs)) or b.wheelchair = 'full')
      and (not ('gender_neutral' = any(needs)) or b.gender_neutral is true)
      and (not ('adult_changing' = any(needs)) or b.adult_changing in ('changing_places','bench'))
      and (not ('hoist'          = any(needs)) or b.adult_changing = 'changing_places')
      and (not ('grab_bars'      = any(needs)) or b.grab_bars is true)
      and (not ('turning_space'  = any(needs)) or b.turning_space is true)
      and (not ('sink_in_stall'  = any(needs)) or b.sink_in_stall is true)
      and (not ('shelf'          = any(needs)) or b.shelf is true)
      and (not ('unlocked'       = any(needs)) or b.accessible_locked is false)
      -- Only what can be computed. 'venue' means the café's hours decide, and
      -- this database does not know them.
      and (not ('open_now' = any(needs)) or b.hours = 'always' or (
        b.hours = 'daylight'
        and extract(hour from (now() at time zone 'America/New_York')) between 7 and 19
      ))
    ))
  order by f.confirms_90d desc nulls last
  limit max_results;
$$;
CREATE FUNCTION restroom.can_view_code(p_user uuid, p_bathroom uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$ select true; $$;
CREATE FUNCTION restroom.daily_passive(p_user uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
  select count(*)::int from credit_ledger
  where user_id = p_user
    and reason = 'passive_confirmation'
    and created_at > now() - interval '24 hours';
$$;
CREATE FUNCTION restroom.daily_submissions(p_user uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
  select count(*)::int from bathrooms
  where created_by = p_user and created_at > now() - interval '24 hours';
$$;
CREATE FUNCTION restroom.get_code(p_bathroom_id uuid) RETURNS TABLE(code text, submitted_at timestamp with time zone, confirms integer, locked boolean, cost integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_live   record;
  v_may    boolean := can_view_code(auth.uid(), p_bathroom_id);
begin
  select bc.id, bc.code, bc.created_at into v_live
  from bathroom_codes bc
  where bc.bathroom_id = p_bathroom_id and bc.superseded_at is null
  limit 1;

  if not found then
    return;   -- no code recorded; nothing to lock or reveal
  end if;

  return query select
    case when v_may then v_live.code else null end,
    v_live.created_at,
    (select count(*)::int from reports r
     where r.code_id = v_live.id and r.kind = 'works'),
    not v_may,
    unlock_cost();
end $$;
CREATE FUNCTION restroom.is_banned(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
  select coalesce(
    (select banned_at is not null from profiles where id = p_user), false);
$$;
CREATE FUNCTION restroom.owns_bathroom(p_user uuid, p_bathroom uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
  select exists (
    select 1 from bathrooms
    where id = p_bathroom and created_by = p_user);   -- sees all rows
$$;
CREATE FUNCTION restroom.promote_access_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $_$
declare
  v_winner text;
  v_winners int;
begin
  select count(*), min(value) into v_winners, v_winner
  from (
    select value from access_claims
    where bathroom_id = NEW.bathroom_id and field = NEW.field
    group by value having count(*) >= 2
  ) agreed;

  if v_winners = 1 then
    execute format(
      'update bathrooms set %I = $1::%s where id = $2 and %I is null',
      NEW.field,
      case NEW.field::text
        when 'wheelchair'     then 'wheelchair_access'
        when 'changing_table' then 'changing_table_access'
        when 'adult_changing' then 'adult_changing_kind'
        when 'hours'          then 'hours_kind'
        else 'boolean'
      end,
      NEW.field)
    using v_winner, NEW.bathroom_id;
  end if;

  return NEW;
end $_$;
CREATE FUNCTION restroom.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;
CREATE FUNCTION restroom.settled_value(p_bathroom uuid, p_field restroom.access_field) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $_$
declare v text;
begin
  execute format('select %I::text from bathrooms where id = $1', p_field)
    into v using p_bathroom;
  return v;
end $_$;
CREATE FUNCTION restroom.submit_access_claim(p_bathroom_id uuid, p_field text, p_value text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_user  uuid := auth.uid();
  v_field access_field;
  v_ok    boolean;
begin
  if v_user is null then
    raise exception 'sign in to add accessibility detail' using errcode = '42501';
  end if;
  if is_banned(v_user) then
    raise exception 'this account cannot submit' using errcode = '42501';
  end if;

  begin
    v_field := p_field::access_field;
  exception when invalid_text_representation then
    raise exception 'unknown field: %', p_field using errcode = '22023';
  end;

  if not exists (select 1 from bathrooms
                 where id = p_bathroom_id and status = 'active') then
    raise exception 'no such place' using errcode = 'P0002';
  end if;

  v_ok := case p_field
    when 'wheelchair'     then p_value in ('full','partial','none')
    when 'changing_table' then p_value in ('any','women_only','men_only','none')
    when 'adult_changing' then p_value in ('changing_places','bench','none')
    when 'hours'          then p_value in ('always','daylight','venue')
    else p_value in ('true','false')
  end;
  if not v_ok then
    raise exception 'not a valid answer for %: %', p_field, p_value
      using errcode = '22023';
  end if;

  if settled_value(p_bathroom_id, v_field) is not null then
    return jsonb_build_object('ok', false, 'reason', 'already_settled');
  end if;

  if not rl_take('claim:' || client_fingerprint(), interval '1 hour', 60) then
    raise exception 'that is a lot of detail at once, try later'
      using errcode = '53400';
  end if;

  values (p_bathroom_id, v_field, p_value, v_user)
  on conflict (bathroom_id, field, user_id)
    do update set value = excluded.value, created_at = now();

  return jsonb_build_object(
    'ok', true,
    'settled', settled_value(p_bathroom_id, v_field) is not null);
end $$;
CREATE FUNCTION restroom.submit_bathroom(p_name text, p_lat double precision, p_lng double precision, p_venue_type text, p_access_kind text, p_address text DEFAULT NULL::text, p_floor_hint text DEFAULT NULL::text, p_code text DEFAULT NULL::text, p_wheelchair text DEFAULT NULL::text, p_changing_table text DEFAULT NULL::text, p_gender_neutral boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_user uuid := auth.uid();
  v_geog geography(Point,4326);
  v_near record;
  v_id   uuid;
begin
  if v_user is null then
    raise exception 'sign in to add a place' using errcode = '42501';
  end if;
  if is_banned(v_user) then
    raise exception 'this account cannot submit' using errcode = '42501';
  end if;
  if coalesce(length(trim(p_name)), 0) = 0 then
    raise exception 'a name is required' using errcode = '22023';
  end if;
  if p_lat is null or p_lng is null
     or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    raise exception 'a valid location is required' using errcode = '22023';
  end if;
  if daily_submissions(v_user) >= 5 then
    raise exception 'that is enough submissions for one day' using errcode = '53400';
  end if;

  v_geog := st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography;

  select b.id, b.name into v_near
  from bathrooms b
  where b.status = 'active' and st_dwithin(b.geog, v_geog, 20)
  limit 1;

  if found then
    return jsonb_build_object(
      'ok', false, 'reason', 'duplicate',
      'existing_id', v_near.id, 'existing_name', v_near.name);
  end if;

    geog, name, venue_type, access_kind, address, floor_hint,
    wheelchair, changing_table, gender_neutral, created_by)
  values (
    v_geog, trim(p_name), p_venue_type::venue_type, p_access_kind::access_kind,
    nullif(trim(p_address), ''), nullif(trim(p_floor_hint), ''),
    p_wheelchair::wheelchair_access, p_changing_table::changing_table_access,
    p_gender_neutral, v_user)
  returning id into v_id;

  if nullif(trim(p_code), '') is not null then
    values (v_id, trim(p_code), v_user);
  end if;

  return jsonb_build_object('ok', true, 'id', v_id);
end $$;
CREATE FUNCTION restroom.submit_code(p_bathroom_id uuid, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_user uuid := auth.uid();
  v_old  uuid;
  v_new  uuid;
begin
  if v_user is null then
    raise exception 'sign in to add a code' using errcode = '42501';
  end if;
  if is_banned(v_user) then
    raise exception 'this account cannot submit' using errcode = '42501';
  end if;
  if coalesce(length(trim(p_code)), 0) = 0 then
    raise exception 'a code is required' using errcode = '22023';
  end if;
  if not exists (select 1 from bathrooms
                 where id = p_bathroom_id and status = 'active') then
    raise exception 'no such place' using errcode = 'P0002';
  end if;

  select id into v_old from bathroom_codes
  where bathroom_id = p_bathroom_id and superseded_at is null;

  -- Same code again is a confirmation, not a change. Leave history alone.
  if v_old is not null and
     (select code from bathroom_codes where id = v_old) = trim(p_code) then
    return jsonb_build_object('ok', true, 'changed', false, 'id', v_old);
  end if;

  -- Retire the incumbent BEFORE inserting, or codes_one_live rejects the pair.
  if v_old is not null then
    update bathroom_codes set superseded_at = now() where id = v_old;
  end if;

  values (p_bathroom_id, trim(p_code), v_user)
  returning id into v_new;

  if v_old is not null then
    update bathroom_codes set superseded_by = v_new where id = v_old;
  end if;

  return jsonb_build_object('ok', true, 'changed', true, 'id', v_new);
end $$;
CREATE FUNCTION restroom.submit_report(p_bathroom_id uuid, p_kind text, p_code_id uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_user   uuid := auth.uid();
  v_kind   report_kind;
  v_fp     text := client_fingerprint();
  v_geo    boolean := false;
  v_code   uuid;
  v_row    record;
begin
  begin
    v_kind := p_kind::report_kind;
  exception when invalid_text_representation then
    raise exception 'unknown report kind: %', p_kind using errcode = '22023';
  end;

  perform 1 from bathrooms where id = p_bathroom_id and status = 'active';
  if not found then
    raise exception 'no such bathroom' using errcode = 'P0002';
  end if;

  if owns_bathroom(v_user, p_bathroom_id) then
    raise exception 'you cannot report your own submission' using errcode = '42501';
  end if;

  if not rl_take('ip:' || v_fp, interval '1 hour', 40) then
    raise exception 'too many reports, try later' using errcode = '53400';
  end if;

  if not rl_take(
       'rpt:' || v_fp || ':' || p_bathroom_id::text || ':' || p_kind,
       interval '1 day', 1) then
    return jsonb_build_object('ok', false, 'reason', 'already_reported');
  end if;

  if p_lat is not null and p_lng is not null then
    select st_dwithin(b.geog,
             st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography, 150)
      into v_geo
    from bathrooms b where b.id = p_bathroom_id;
  end if;

  -- Whatever the caller claimed, attach to the code currently live.
  select id into v_code from bathroom_codes
  where bathroom_id = p_bathroom_id and superseded_at is null;

  begin
    values (p_bathroom_id, v_code, v_user,
            case when v_user is null then left(v_fp, 16) end,
            v_kind, coalesce(v_geo, false));
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'reason', 'already_reported');
  end;

  select coalesce(confirms_90d, 0) as confirms,
         coalesce(troubles_90d, 0) as troubles,
         last_confirmed_at
    into v_row
  from bathroom_confidence where bathroom_id = p_bathroom_id;

  return jsonb_build_object(
    'ok', true,
    'geo_verified', coalesce(v_geo, false),
    'confirms', coalesce(v_row.confirms, 0),
    'troubles', coalesce(v_row.troubles, 0),
    'last_confirmed', v_row.last_confirmed_at);
end $$;
CREATE FUNCTION restroom.unlock_code(p_bathroom_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'restroom', 'public', 'extensions'
    AS $$
declare
  v_user    uuid := auth.uid();
  v_cost    int  := unlock_cost();
  v_balance int;
  v_code    text;
begin
  if v_user is null then
    raise exception 'sign in to unlock a code' using errcode = '42501';
  end if;

  -- Serialise this user's spending. Without the lock, two unlocks issued at
  -- once both read the old balance and a 2-credit account buys two doors.
  perform 1 from profiles where id = v_user for update;

  if can_view_code(v_user, p_bathroom_id) then
    select bc.code into v_code from bathroom_codes bc
    where bc.bathroom_id = p_bathroom_id and bc.superseded_at is null;
    return jsonb_build_object('ok', true, 'charged', 0, 'code', v_code);
  end if;

  select bc.code into v_code from bathroom_codes bc
  where bc.bathroom_id = p_bathroom_id and bc.superseded_at is null;
  if v_code is null then
    raise exception 'no code recorded for that place' using errcode = 'P0002';
  end if;

  select coalesce(sum(delta), 0)::int into v_balance
  from credit_ledger where user_id = v_user;

  if v_balance < v_cost then
    return jsonb_build_object(
      'ok', false, 'reason', 'insufficient',
      'balance', v_balance, 'cost', v_cost);
  end if;

  values (v_user, -v_cost, 'spend_unlock', 'bathroom', p_bathroom_id);

  values (v_user, p_bathroom_id)
  on conflict do nothing;

  return jsonb_build_object(
    'ok', true, 'charged', v_cost, 'code', v_code,
    'balance', v_balance - v_cost);
end $$;
CREATE FUNCTION restroom.unlock_cost() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ select 2; $$;
CREATE INDEX access_claims_tally ON restroom.access_claims USING btree (bathroom_id, field, value);
CREATE INDEX bathrooms_accessible ON restroom.bathrooms USING btree (wheelchair) WHERE ((status = 'active'::restroom.bathroom_status) AND (wheelchair IS NOT NULL));
CREATE INDEX bathrooms_changing ON restroom.bathrooms USING btree (changing_table) WHERE ((status = 'active'::restroom.bathroom_status) AND (changing_table IS NOT NULL));
CREATE INDEX bathrooms_geog_idx ON restroom.bathrooms USING gist (geog);
CREATE INDEX bathrooms_hours ON restroom.bathrooms USING btree (hours) WHERE ((status = 'active'::restroom.bathroom_status) AND (hours IS NOT NULL));
CREATE UNIQUE INDEX bathrooms_import_key ON restroom.bathrooms USING btree (import_source, import_id) WHERE (import_source IS NOT NULL);
CREATE INDEX bathrooms_imported ON restroom.bathrooms USING btree (import_source) WHERE (import_source IS NOT NULL);
CREATE INDEX bathrooms_live_idx ON restroom.bathrooms USING btree (venue_type, access_kind) WHERE (status = 'active'::restroom.bathroom_status);
CREATE INDEX bathrooms_operator ON restroom.bathrooms USING btree (operator) WHERE ((status = 'active'::restroom.bathroom_status) AND (operator IS NOT NULL));
CREATE UNIQUE INDEX codes_one_live ON restroom.bathroom_codes USING btree (bathroom_id) WHERE (superseded_at IS NULL);
CREATE UNIQUE INDEX ledger_dedupe ON restroom.credit_ledger USING btree (user_id, reason, ref_id) WHERE (ref_id IS NOT NULL);
CREATE UNIQUE INDEX reports_daily_cap ON restroom.reports USING btree (bathroom_id, user_id, kind, date_trunc('day'::text, (created_at AT TIME ZONE 'utc'::text))) WHERE (user_id IS NOT NULL);
CREATE INDEX reports_recent ON restroom.reports USING btree (bathroom_id, created_at DESC);
CREATE TRIGGER access_claims_promote AFTER INSERT OR UPDATE ON restroom.access_claims FOR EACH ROW EXECUTE FUNCTION restroom.promote_access_claim();
CREATE TRIGGER reports_auto_hide AFTER INSERT ON restroom.reports FOR EACH ROW EXECUTE FUNCTION restroom.apply_auto_hide();
CREATE TRIGGER reports_award AFTER INSERT ON restroom.reports FOR EACH ROW EXECUTE FUNCTION restroom.award_on_report();
CREATE POLICY bathrooms_read ON restroom.bathrooms FOR SELECT USING ((status = 'active'::restroom.bathroom_status));
CREATE POLICY claims_read ON restroom.access_claims FOR SELECT TO authenticated, anon USING (true);
CREATE POLICY comments_delete_own ON restroom.comments FOR DELETE TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY comments_insert ON restroom.comments FOR INSERT TO authenticated WITH CHECK (((user_id = auth.uid()) AND (NOT restroom.is_banned(auth.uid()))));
CREATE POLICY comments_read ON restroom.comments FOR SELECT USING ((hidden_at IS NULL));
CREATE POLICY ledger_read_own ON restroom.credit_ledger FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY reports_read ON restroom.reports FOR SELECT USING (true);
CREATE POLICY unlocks_read_own ON restroom.code_unlocks FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE VIEW restroom.access_claim_state WITH (security_invoker='true') AS
 WITH tally AS (
         SELECT access_claims.bathroom_id,
            access_claims.field,
            access_claims.value,
            (count(*))::integer AS claims
           FROM restroom.access_claims
          GROUP BY access_claims.bathroom_id, access_claims.field, access_claims.value
        )
 SELECT bathroom_id,
    field,
    value,
    claims,
    (count(*) OVER (PARTITION BY bathroom_id, field) > 1) AS disputed
   FROM tally t
  WHERE (restroom.settled_value(bathroom_id, field) IS NULL);

